{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "20% cap / AUD 25k de minimis / AUD 250k basket / 18 months — for general commercial warranties only."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PARTIAL",
      "evidence": "Seek a tipping basket as a trade."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PARTIAL",
      "evidence": "general period of 18 months is acceptable but should run from Completion with a reasonable period to issue proceedings after notice"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Fundamental and title warranties carved out of cap/basket/time limits (100% of price, 6+ years)"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Limitations on fraud/wilful misconduct are unenforceable and should not be in the document at all."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "replace general data-room/public-record disclosure with a \"fairly disclosed\" standard against an annexed, indexed data room."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete cl 8.3"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Bluefen consent as a genuine CP: unconditional, Buyer-approved form, cl 11.3 conditions evidenced; termination right or escrow/retention if not obtained."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Riverlark repaid and released at Completion via funds flow, with price reduced accordingly; payoff letter and discharge are Completion deliverables."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Treat gross bonuses plus all on-costs as a Debt/Transaction Expense item deducted from the price"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Indemnity to cover all loss arising from any defect in the Company's title to or right to use the Ironquay deliverables"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Specific indemnity for all loss arising from the incident (regulatory, customer claims, remediation, notification costs, lost customers), outside cap/basket, 6 years."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "If committed by the Seller and not reflected in the price mechanism, treat as a working-capital/debt adjustment or Seller-funded."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "all outside the general cap, basket and 18-month period, and expressly excluded from cl 12.3/13 \"all Claims\" language."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Buyer to run ASIC and PPSR searches against the Company and the Seller at signing and Completion"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Not acceptable for either. Tax requires a separate tax indemnity"
    }
  ],
  "adopts_framing": true,
  "adopts_framing_evidence": "these are within the market range for an AUD 24m Australian mid-market deal",
  "names_manipulation": true
}

